From 2a8bf9c58d862b0c76a35ce288d1ba6a27223aad Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Thu, 27 Aug 2026 19:51:28 +0200
Subject: [PATCH 01/15] [Yaml] Bound recursion depth in the inline lexer

`Parser::lexInlineStructure()` self-recurses on `{` and `[` without any
nesting guard. The lexer runs to completion before `Inline::parse()` is
called, so the `maxNestingLevel` limit enforced by the block parser and
by `Inline::parseSequence()` / `Inline::parseMapping()` is never reached
for deeply nested inline input.

Track the depth in the shared `ParserState` while lexing, so that the
same limit applies. Without it, about 70 KB of `[` exhausts a 128 MB
memory limit before any guard runs.

(cherry picked from commit 2c5677e4f5cd44978bbe58d5122a5f0a19425ebb)
---
 src/Symfony/Component/Yaml/Parser.php         | 12 ++++++++
 .../Component/Yaml/Tests/ParserTest.php       | 28 +++++++++++++++++++
 2 files changed, 40 insertions(+)

diff --git a/src/Symfony/Component/Yaml/Parser.php b/src/Symfony/Component/Yaml/Parser.php
index f8e79a9423fe6..2c67b2d05fa7b 100644
--- a/src/Symfony/Component/Yaml/Parser.php
+++ b/src/Symfony/Component/Yaml/Parser.php
@@ -1274,6 +1274,18 @@ private function lexInlineSequence(int &$cursor = 0): string
     }

     private function lexInlineStructure(int &$cursor, string $closingTag): string
+    {
+        $state = $this->getState();
+        $state->enterNestingLevel($this->getRealCurrentLineNb() + 1, $this->currentLine, $this->filename);
+
+        try {
+            return $this->doLexInlineStructure($cursor, $closingTag);
+        } finally {
+            $state->leaveNestingLevel();
+        }
+    }
+
+    private function doLexInlineStructure(int &$cursor, string $closingTag): string
     {
         $value = $this->currentLine[$cursor];
         ++$cursor;
diff --git a/src/Symfony/Component/Yaml/Tests/ParserTest.php b/src/Symfony/Component/Yaml/Tests/ParserTest.php
index c3d04fc8ecc8b..67766b82c1ee0 100644
--- a/src/Symfony/Component/Yaml/Tests/ParserTest.php
+++ b/src/Symfony/Component/Yaml/Tests/ParserTest.php
@@ -2967,6 +2967,34 @@ public function testParseRejectsDocumentsThatExceedTheDefaultNestingDepth()
         $this->parser->parse($yaml);
     }

+    public function testParseRejectsUnterminatedInlineSequencesThatExceedTheNestingDepth()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Maximum nesting depth of 128 exceeded');
+
+        $this->parser->parse(str_repeat('[', Parser::DEFAULT_MAX_NESTING_LEVEL + 1));
+    }
+
+    public function testParseRejectsUnterminatedInlineMappingsThatExceedTheNestingDepth()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Maximum nesting depth of 128 exceeded');
+
+        $this->parser->parse(str_repeat('{', Parser::DEFAULT_MAX_NESTING_LEVEL + 1));
+    }
+
+    public function testParseAcceptsInlineSequencesAtTheNestingDepth()
+    {
+        $expected = [];
+        for ($i = 1; $i < Parser::DEFAULT_MAX_NESTING_LEVEL; ++$i) {
+            $expected = [$expected];
+        }
+
+        $yaml = str_repeat('[', Parser::DEFAULT_MAX_NESTING_LEVEL).str_repeat(']', Parser::DEFAULT_MAX_NESTING_LEVEL);
+
+        $this->assertSame($expected, $this->parser->parse($yaml));
+    }
+
     public function testParseRejectsDocumentsThatExceedTheConfiguredCollectionAliasLimit()
     {
         $parser = new Parser(Parser::DEFAULT_MAX_NESTING_LEVEL, 5);

From 343a1772ce6ac03e48b228d2d7168d19750e3f36 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Mon, 14 Sep 2026 11:49:55 +0200
Subject: [PATCH 02/15] [HttpFoundation] Remove the ambiguity that makes
 HeaderUtils::split() backtrack

The token branch of the pattern matched whitespace, so a run of whitespace
before a separator could be split between the iterations of the enclosing
quantifier in as many ways as it had characters, and the trailing assertion
forced the engine to enumerate them. Parsing a header holding such runs cost
seconds of CPU, and past the backtracking limit the match failed altogether
and the header was silently parsed as nothing.

Whitespace is now consumed only when more of the value follows it. A value can
therefore never end on whitespace, nothing has to be given back, and every
quantifier can be possessive. What the separator branch sees is unchanged.
Whitespace characters used as separators are left out of the whitespace branch,
so splitting "foo bar" on a space still returns two values.

(cherry picked from commit 47f3a4e2c52a687b2cee188a3ac2275ab5302833)
(cherry picked from commit 9ffa802e5d7e9fb8ba95eeefd27e863e83b1baca)
---
 .../Component/HttpFoundation/HeaderUtils.php  |  9 +++++---
 .../HttpFoundation/Tests/HeaderUtilsTest.php  | 22 ++++++++++++++++++-
 2 files changed, 27 insertions(+), 4 deletions(-)

diff --git a/src/Symfony/Component/HttpFoundation/HeaderUtils.php b/src/Symfony/Component/HttpFoundation/HeaderUtils.php
index 110896e1776d1..697b31823b2cd 100644
--- a/src/Symfony/Component/HttpFoundation/HeaderUtils.php
+++ b/src/Symfony/Component/HttpFoundation/HeaderUtils.php
@@ -58,9 +58,12 @@ public static function split(string $header, string $separators): array
                         "(?:[^"\\\\]|\\\\.)*(?:"|\\\\|$)
                     |
                         # token
-                        [^"'.$quotedSeparators.']+
-                    )+
-                (?<!\s)
+                        [^"\s'.$quotedSeparators.']++
+                    |
+                        # whitespace that is not a separator, only when more of the value follows it,
+                        # so that a value never ends on whitespace and none of it ever has to be given back
+                        [^\S'.$quotedSeparators.']++(?!['.$quotedSeparators.']|$)
+                    )++
             |
                 # separator
                 \s*
diff --git a/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php b/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php
index 3279b9a53b47d..28de1e2fd3a89 100644
--- a/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php
+++ b/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php
@@ -43,6 +43,10 @@ public static function provideHeaderToSplit(): array
             [['foo bar'], 'foo "bar"', ','],
             [['foo bar'], '"foo" bar', ','],
             [['foo bar'], '"foo" "bar"', ','],
+            [['foo', 'bar'], 'foo bar', ' '],
+            [['foo', 'bar'], 'foo   bar', ' '],
+            [[['foo', 'bar'], ['baz']], 'foo bar, baz', ', '],
+            [['foo bar', 'baz'], "foo bar\tbaz", "\t"],

             [[['foo_cookie', 'foo=1&bar=2&baz=3'], ['expires', 'Tue, 22-Sep-2020 06:27:09 GMT'], ['path', '/']], 'foo_cookie=foo=1&bar=2&baz=3; expires=Tue, 22-Sep-2020 06:27:09 GMT; path=/', ';='],
             [[['foo_cookie', 'foo=='], ['expires', 'Tue, 22-Sep-2020 06:27:09 GMT'], ['path', '/']], 'foo_cookie=foo==; expires=Tue, 22-Sep-2020 06:27:09 GMT; path=/', ';='],
@@ -183,4 +187,20 @@ public function testParseQueryIgnoreBrackets()
         $this->assertSame(['a.b[]' => ['A']], HeaderUtils::parseQuery('a.b[]=A', true));
         $this->assertSame(['a.b[]' => ['A']], HeaderUtils::parseQuery('a.b%5B%5D=A', true));
     }
-}
+
+    /**
+     * A run of whitespace before a separator must not make the parser give up: the token branch
+     * of the pattern used to match that whitespace and hand it back one character at a time.
+     */
+    public function testSplitIsNotAmbiguousAboutWhitespaceBeforeSeparators()
+    {
+        $this->assertSame([["a"], ["b"]], HeaderUtils::split("a".str_repeat(" ", 25).",b", ",="));
+        $this->assertSame([[["a"]], [["b"]]], HeaderUtils::split("a".str_repeat(" ", 25).",b", ",;="));
+        $this->assertSame([["x", "1"], ["y", "2"]], HeaderUtils::split("x=1".str_repeat(" ", 25).";y=2", ";="));
+
+        $header = str_repeat("a".str_repeat(" ", 25).",", 200);
+        $this->assertCount(200, HeaderUtils::split($header, ",="));
+
+        // whitespace inside a value is still part of it
+        $this->assertSame([["a b  c"]], HeaderUtils::split("a b  c", ",="));
+    }}

From 54bbbdf19050bc633bcca06aa011395b2c842e21 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:28:26 +0200
Subject: [PATCH 03/15] [Yaml] Fix the return types of
 ParseException::getParsedFile() and getSnippet()

Both properties are nullable, so both getters threw a TypeError when the YAML came from a string or when the exception had no snippet.
---
 src/Symfony/Component/Yaml/Exception/ParseException.php | 4 ++--
 src/Symfony/Component/Yaml/Tests/ParseExceptionTest.php | 8 ++++++++
 2 files changed, 10 insertions(+), 2 deletions(-)

diff --git a/src/Symfony/Component/Yaml/Exception/ParseException.php b/src/Symfony/Component/Yaml/Exception/ParseException.php
index 35b948adb3eaf..71d0cb860d9aa 100644
--- a/src/Symfony/Component/Yaml/Exception/ParseException.php
+++ b/src/Symfony/Component/Yaml/Exception/ParseException.php
@@ -44,7 +44,7 @@ public function __construct(string $message, int $parsedLine = -1, ?string $snip
     /**
      * Gets the snippet of code near the error.
      */
-    public function getSnippet(): string
+    public function getSnippet(): ?string
     {
         return $this->snippet;
     }
@@ -66,7 +66,7 @@ public function setSnippet(string $snippet)
      *
      * This method returns null if a string is parsed.
      */
-    public function getParsedFile(): string
+    public function getParsedFile(): ?string
     {
         return $this->parsedFile;
     }
diff --git a/src/Symfony/Component/Yaml/Tests/ParseExceptionTest.php b/src/Symfony/Component/Yaml/Tests/ParseExceptionTest.php
index 39579ede7256f..3d4ec6517ec45 100644
--- a/src/Symfony/Component/Yaml/Tests/ParseExceptionTest.php
+++ b/src/Symfony/Component/Yaml/Tests/ParseExceptionTest.php
@@ -31,4 +31,12 @@ public function testGetMessageWithUnicodeInFilename()

         $this->assertEquals($message, $exception->getMessage());
     }
+
+    public function testGettersReturnNullWhenNoFileOrSnippetIsSet()
+    {
+        $exception = new ParseException('Error message');
+
+        $this->assertNull($exception->getParsedFile());
+        $this->assertNull($exception->getSnippet());
+    }
 }

From cadb78b2acaa52f5e5e0a92a77581cd6cd73ee1d Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:28:57 +0200
Subject: [PATCH 04/15] [Yaml] Fix a PHP warning when an inline sequence or
 mapping ends with an anchor

The tag lookup that follows an anchor read past the end of the string before the "Malformed inline YAML string" exception was thrown.
---
 src/Symfony/Component/Yaml/Inline.php           |  2 +-
 src/Symfony/Component/Yaml/Tests/InlineTest.php | 16 ++++++++++++++++
 2 files changed, 17 insertions(+), 1 deletion(-)

diff --git a/src/Symfony/Component/Yaml/Inline.php b/src/Symfony/Component/Yaml/Inline.php
index f2a176a15b0f9..b657648269b9f 100644
--- a/src/Symfony/Component/Yaml/Inline.php
+++ b/src/Symfony/Component/Yaml/Inline.php
@@ -897,7 +897,7 @@ private static function parseAnchor(string $value, int &$i): ?string

     private static function parseTag(string $value, int &$i, int $flags): ?string
     {
-        if ('!' !== $value[$i]) {
+        if (!isset($value[$i]) || '!' !== $value[$i]) {
             return null;
         }

diff --git a/src/Symfony/Component/Yaml/Tests/InlineTest.php b/src/Symfony/Component/Yaml/Tests/InlineTest.php
index ce8bc051ed342..6a72514db79c1 100644
--- a/src/Symfony/Component/Yaml/Tests/InlineTest.php
+++ b/src/Symfony/Component/Yaml/Tests/InlineTest.php
@@ -870,6 +870,22 @@ public function testUnterminatedMappingEndingWithTag()
         Inline::parse('{foo: !bar', Yaml::PARSE_CUSTOM_TAGS);
     }

+    public function testUnterminatedSequenceEndingWithAnchor()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Malformed inline YAML string: "[&:"');
+
+        Inline::parse('[&:');
+    }
+
+    public function testUnterminatedMappingEndingWithAnchor()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Malformed inline YAML string: "{foo: &bar"');
+
+        Inline::parse('{foo: &bar');
+    }
+
     public function testVeryLongQuotedStrings()
     {
         $longStringWithQuotes = str_repeat("x\r\n\\\"x\"x", 1000);

From f48b9cf46753b579645ef0a26bd2872a97e13636 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:29:27 +0200
Subject: [PATCH 05/15] [Yaml] Fix a TypeError when an enum case is used as a
 flow mapping key

A !php/const or !php/enum key that is not a string or an integer now throws the same ParseException as in block mappings.
---
 src/Symfony/Component/Yaml/Inline.php           | 4 ++++
 src/Symfony/Component/Yaml/Tests/InlineTest.php | 8 ++++++++
 2 files changed, 12 insertions(+)

diff --git a/src/Symfony/Component/Yaml/Inline.php b/src/Symfony/Component/Yaml/Inline.php
index b657648269b9f..a0e5b7a08c881 100644
--- a/src/Symfony/Component/Yaml/Inline.php
+++ b/src/Symfony/Component/Yaml/Inline.php
@@ -521,6 +521,10 @@ private static function parseMapping(ParserState $state, string $mapping, int $f
                 if ('!php/const' === $key || '!php/enum' === $key) {
                     $key .= ' '.self::parseScalar($mapping, $flags, ['(?<!:):(?!:)'], $i, false);
                     $key = self::evaluateScalar($state, $key, $flags);
+
+                    if (!\is_string($key) && !\is_int($key)) {
+                        throw new ParseException((is_numeric($key) ? 'Numeric' : 'Non-string').' keys are not supported. Quote your evaluable mapping keys instead.', self::$parsedLineNumber + 1, $mapping);
+                    }
                 }

                 if (self::$objectForMap && \is_string($key) && str_starts_with($key, "\0")) {
diff --git a/src/Symfony/Component/Yaml/Tests/InlineTest.php b/src/Symfony/Component/Yaml/Tests/InlineTest.php
index 6a72514db79c1..beadefe9fc193 100644
--- a/src/Symfony/Component/Yaml/Tests/InlineTest.php
+++ b/src/Symfony/Component/Yaml/Tests/InlineTest.php
@@ -795,6 +795,14 @@ public function testParseBackedEnumValue()
         $this->assertSame(FooBackedEnum::BAR->value, Inline::parse("!php/enum Symfony\Component\Yaml\Tests\Fixtures\FooBackedEnum::BAR->value", Yaml::PARSE_CONSTANT));
     }

+    public function testParseEnumAsMappingKeyThrowsException()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Non-string keys are not supported. Quote your evaluable mapping keys instead');
+
+        Inline::parse("{!php/const Symfony\Component\Yaml\Tests\Fixtures\FooBackedEnum::BAR: 1}", Yaml::PARSE_CONSTANT);
+    }
+
     public static function getDateTimeDumpTests()
     {
         $tests = [];

From 1d148e837ad0f268e133b431b9ee6b8e2f7adc55 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:30:43 +0200
Subject: [PATCH 06/15] [Yaml] Fix a TypeError when a merge key sequence
 contains a tagged value or an object

The item was passed as the snippet of the "Merge items must be arrays" exception, which only accepts a string.
---
 src/Symfony/Component/Yaml/Parser.php           | 2 +-
 src/Symfony/Component/Yaml/Tests/ParserTest.php | 8 ++++++++
 2 files changed, 9 insertions(+), 1 deletion(-)

diff --git a/src/Symfony/Component/Yaml/Parser.php b/src/Symfony/Component/Yaml/Parser.php
index e840f9ba02998..b9994649e5bcd 100644
--- a/src/Symfony/Component/Yaml/Parser.php
+++ b/src/Symfony/Component/Yaml/Parser.php
@@ -350,7 +350,7 @@ private function doParse(string $value, int $flags): mixed
                                 }

                                 if (!\is_array($parsedItem)) {
-                                    throw new ParseException('Merge items must be arrays.', $this->getRealCurrentLineNb() + 1, $parsedItem, $this->filename);
+                                    throw new ParseException('Merge items must be arrays.', $this->getRealCurrentLineNb() + 1, \is_scalar($parsedItem) ? $parsedItem : null, $this->filename);
                                 }

                                 $data += $parsedItem; // array union
diff --git a/src/Symfony/Component/Yaml/Tests/ParserTest.php b/src/Symfony/Component/Yaml/Tests/ParserTest.php
index f9ecf7843950a..9bea38c053ed7 100644
--- a/src/Symfony/Component/Yaml/Tests/ParserTest.php
+++ b/src/Symfony/Component/Yaml/Tests/ParserTest.php
@@ -3259,6 +3259,14 @@ public function testParseMergeKeyFollowedByATab()
         ));
     }

