+        $this->parser->parse("<<:\n  - !foo bar\n", Yaml::PARSE_CUSTOM_TAGS);
+    }
+
     public function testParseReferencesOnMergeKeysWithMappingsParsedAsObjects()
     {
         $yaml = <<<YAML

From 883c0b32650fd958389d52c58ca19e59c40d0461 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:39:50 +0200
Subject: [PATCH 07/15] [Yaml] Fix flow mapping keys from string constants
 being evaluated twice

The value of a !php/const or !php/enum key was parsed again as YAML, so "true" or "*foo" were rejected and "<<" became a merge key. They are now used as is, like in block mappings.
---
 src/Symfony/Component/Yaml/Inline.php           |  8 +++++---
 src/Symfony/Component/Yaml/Tests/ParserTest.php | 10 ++++++++++
 2 files changed, 15 insertions(+), 3 deletions(-)

diff --git a/src/Symfony/Component/Yaml/Inline.php b/src/Symfony/Component/Yaml/Inline.php
index a0e5b7a08c881..c7c82d34ccb7d 100644
--- a/src/Symfony/Component/Yaml/Inline.php
+++ b/src/Symfony/Component/Yaml/Inline.php
@@ -518,7 +518,9 @@ private static function parseMapping(ParserState $state, string $mapping, int $f
                     throw new ParseException('Missing mapping key.', self::$parsedLineNumber + 1, $mapping);
                 }

-                if ('!php/const' === $key || '!php/enum' === $key) {
+                $isKeyEvaluated = '!php/const' === $key || '!php/enum' === $key;
+
+                if ($isKeyEvaluated) {
                     $key .= ' '.self::parseScalar($mapping, $flags, ['(?<!:):(?!:)'], $i, false);
                     $key = self::evaluateScalar($state, $key, $flags);

@@ -535,7 +537,7 @@ private static function parseMapping(ParserState $state, string $mapping, int $f
                     break;
                 }

-                if (!$isKeyQuoted) {
+                if (!$isKeyQuoted && !$isKeyEvaluated) {
                     $evaluatedKey = self::evaluateScalar($state, $key, $flags, $references);

                     if ('' !== $key && $evaluatedKey !== $key && (!\is_string($evaluatedKey) || '!' === $key[0]) && !\is_int($evaluatedKey)) {
@@ -547,7 +549,7 @@ private static function parseMapping(ParserState $state, string $mapping, int $f
                     throw new ParseException('Colons must be followed by a space or an indication character (i.e. " ", ",", "[", "]", "{", "}").', self::$parsedLineNumber + 1, $mapping);
                 }

-                $isMergeKey = !$isKeyQuoted && '<<' === $key;
+                $isMergeKey = !$isKeyQuoted && !$isKeyEvaluated && '<<' === $key;

                 if ($isMergeKey) {
                     $allowOverwrite = true;
diff --git a/src/Symfony/Component/Yaml/Tests/ParserTest.php b/src/Symfony/Component/Yaml/Tests/ParserTest.php
index 9bea38c053ed7..2c83eb7af4311 100644
--- a/src/Symfony/Component/Yaml/Tests/ParserTest.php
+++ b/src/Symfony/Component/Yaml/Tests/ParserTest.php
@@ -3069,6 +3069,13 @@ public function testTagMappingAsScalarKey()
         ], $this->parser->parse($yaml));
     }

+    public function testPhpConstantTagFlowMappingKeyUsesTheConstantValueAsIs()
+    {
+        $yaml = '{!php/const Symfony\Component\Yaml\Tests\B::TRUE_STRING: a, !php/const Symfony\Component\Yaml\Tests\B::ALIAS_STRING: b, !php/const Symfony\Component\Yaml\Tests\B::MERGE_KEY: {c: d}}';
+
+        $this->assertSame(['true' => 'a', '*foo' => 'b', '<<' => ['c' => 'd']], $this->parser->parse($yaml, Yaml::PARSE_CONSTANT));
+    }
+
     public function testMergeKeysWhenMappingsAreParsedAsObjects()
     {
         $yaml = <<<YAML
@@ -3910,4 +3917,7 @@ class B
     public const FOO = 'foo';
     public const BAR = 'bar';
     public const BAZ = 'baz';
+    public const TRUE_STRING = 'true';
+    public const ALIAS_STRING = '*foo';
+    public const MERGE_KEY = '<<';
 }

From 5a8cb50b21ab54f2ad62adb0b8ceead528aadd07 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:41:08 +0200
Subject: [PATCH 08/15] [Yaml] Fix !php/const and !php/enum keys of mappings
 embedded in flow sequences

[!php/const FOO: bar] looked for a constant named "FOO: bar". It now gives the same mapping as [foo: bar] does with a plain key.
---
 src/Symfony/Component/Yaml/Inline.php           | 4 +++-
 src/Symfony/Component/Yaml/Tests/InlineTest.php | 5 +++++
 2 files changed, 8 insertions(+), 1 deletion(-)

diff --git a/src/Symfony/Component/Yaml/Inline.php b/src/Symfony/Component/Yaml/Inline.php
index c7c82d34ccb7d..1e9332a645a84 100644
--- a/src/Symfony/Component/Yaml/Inline.php
+++ b/src/Symfony/Component/Yaml/Inline.php
@@ -420,7 +420,9 @@ private static function parseSequence(ParserState $state, string $sequence, int
                         $value = self::parseMapping($state, $sequence, $flags, $i, $references);
                         break;
                     default:
-                        $value = self::parseScalar($sequence, $flags, [',', ']'], $i, null === $tag, $references, $isQuoted, $state);
+                        // a !php/const or !php/enum key of an embedded mapping is evaluated by parseMapping()
+                        $evaluate = null === $tag && !Parser::preg_match('/!php\/(?:const|enum) [^ ,\]]+?(?<!:): +[^ ,\]]/A', substr($sequence, $i));
+                        $value = self::parseScalar($sequence, $flags, [',', ']'], $i, $evaluate, $references, $isQuoted, $state);

                         // the value can be an array if a reference has been resolved to an array var
                         if (\is_string($value) && !$isQuoted && str_contains($value, ': ')) {
diff --git a/src/Symfony/Component/Yaml/Tests/InlineTest.php b/src/Symfony/Component/Yaml/Tests/InlineTest.php
index beadefe9fc193..e19a740b1fe60 100644
--- a/src/Symfony/Component/Yaml/Tests/InlineTest.php
+++ b/src/Symfony/Component/Yaml/Tests/InlineTest.php
@@ -803,6 +803,11 @@ public function testParseEnumAsMappingKeyThrowsException()
         Inline::parse("{!php/const Symfony\Component\Yaml\Tests\Fixtures\FooBackedEnum::BAR: 1}", Yaml::PARSE_CONSTANT);
     }

+    public function testParsePhpConstantAndEnumAsMappingKeysInSequence()
+    {
+        $this->assertSame([[\PHP_INT_MAX => 'foo'], ['bar' => 'baz']], Inline::parse("[!php/const PHP_INT_MAX: foo, !php/enum Symfony\Component\Yaml\Tests\Fixtures\FooBackedEnum::BAR->value: baz]", Yaml::PARSE_CONSTANT));
+    }
+
     public static function getDateTimeDumpTests()
     {
         $tests = [];

From 505914df42204f9d8f76f37010c0295da9d17324 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Wed, 14 Oct 2026 20:42:34 +0200
Subject: [PATCH 09/15] [Yaml] Fix merge keys that list a null item first or
 that use a mapping with a 0 key

The parser used isset($parsed[0]) to tell a sequence from a mapping. It now looks at the YAML source, like the flow parser does.
---
